SET NOCOUNT ON;SET XACT_ABORT ON;SELECT * FROM lab.Evidence ORDER BY Stage;SELECT vlf_sequence_number,vlf_size_mb,vlf_active,vlf_status FROM sys.dm_db_log_info(DB_ID()) ORDER BY vlf_begin_offset;IF NOT EXISTS(SELECT 1 FROM lab.Evidence a CROSS JOIN lab.Evidence b WHERE a.Stage='SMALL_GROWTH' AND b.Stage='BASELINE' AND a.LogSizeMB>b.LogSizeMB AND a.VlfCount>b.VlfCount) BEGIN PRINT 'SQLPERF_SUMMARY|SKIP|SKIP_EVIDENCE_MISSING';RETURN;END;PRINT 'SQLPERF_SUMMARY|PASS|OK';
